import { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, AmbientLight, DirectionalLight, Color, DoubleSide, MathUtils } from 'three/webgpu';
import { uv, mix, color, float } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, AmbientLight, DirectionalLight, DoubleSide, MathUtils } = ctx.THREE;

  const root = new Group();

  // ---------- BACKDROP ----------
  const backdropGeom = new PlaneGeometry(7, 6);
  const gradientColor = mix(color('#0b0b10'), color('#12121a'), uv().y);
  const backdropMat = new MeshStandardNodeMaterial();
  backdropMat.colorNode = gradientColor;
  backdropMat.roughness = 0.9;
  backdropMat.metalness = 0;
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---------- LIGHTING ----------
  const ambient = new AmbientLight(0xffffff, 0.6);
  root.add(ambient);

  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(1, 1, 2);
  root.add(keyLight);

  const rimLight = new DirectionalLight(0xffffff, 0.8);
  rimLight.position.set(-1, -1, -2);
  root.add(rimLight);

  // ---------- TEXT (HEADLINE & BODY) ----------
  const headlineText = ctx.fontAtlas.createText('The collection', {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'left',
    letterSpacing: -0.005,
  });
  headlineText.position.set(-2.6, 1.5, 0);
  root.add(headlineText);

  const bodyText = ctx.fontAtlas.createText('Five calibres. One discipline.', {
    fontSize: 26,
    color: '#e8ecf2',
    align: 'left',
    letterSpacing: 0,
  });
  bodyText.position.set(-2.6, -1.5, 0);
  root.add(bodyText);

  // ---------- CARD STRIP ----------
  const stripGroup = new Group();
  stripGroup.rotation.y = -MathUtils.degToRad(18);
  root.add(stripGroup);

  // Load shared texture (will be applied to all cards)
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  const cardMaterials = [];

  // Caption strings (order left‑to‑right)
  const captions = [
    'NA-01 MERIDIAN',
    'NA-02 NOCTURNE',
    'NA-03 SIGNAL',
    'NA-04 VANTAGE',
    'NA-05 ARCHIVE',
  ];

  const cardWidth = 1.6;
  const cardHeight = 1.0;
  const pitch = 1.85;
  const totalCards = 5;
  const focusedIndex = 2; // zero based

  for (let i = 0; i < totalCards; i++) {
    const cardGroup = new Group();

    const xPos = (i - focusedIndex) * pitch;
    cardGroup.position.set(xPos, 0, 0);

    // ---- FRAME (bevel) ----
    const frameGeom = new PlaneGeometry(cardWidth + 0.05, cardHeight + 0.05);
    const frameMat = new MeshStandardNodeMaterial({ color: '#16161d', side: DoubleSide });
    frameMat.roughness = 0.6;
    frameMat.metalness = 0;
    const frameMesh = new Mesh(frameGeom, frameMat);
    frameMesh.position.set(0, 0, -0.001); // slight back offset
    cardGroup.add(frameMesh);

    // ---- CARD SURFACE ----
    const cardGeom = new PlaneGeometry(cardWidth, cardHeight);
    const cardMat = new MeshStandardNodeMaterial({
      side: DoubleSide,
      transparent: true,
    });
    cardMat.roughness = 0.55;
    cardMat.metalness = 0.2;
    cardMat.clearcoat = 0.15;

    // Opacity based on distance from focus
    const distance = Math.abs(i - focusedIndex);
    const opacity = 1 - 0.45 * (distance / (totalCards - 1));
    cardMat.opacity = opacity;

    // Scaling
    const scaleFactor = i === focusedIndex ? 1.0 : 0.92;
    cardGroup.scale.setScalar(scaleFactor);

    const cardMesh = new Mesh(cardGeom, cardMat);
    cardMesh.position.set(0, 0, 0);
    cardGroup.add(cardMesh);

    // Store material for later disposal
    cardMaterials.push({ material: cardMat, geometry: cardGeom, frameMat, frameGeom });

    // Set texture when loaded
    texturePromise.then((tex) => {
      cardMat.map = tex;
      cardMat.needsUpdate = true;
    });

    // ---- UNDERLINE FOR FOCUSED CARD ----
    if (i === focusedIndex) {
      const underlineGeom = new PlaneGeometry(cardWidth, 0.035);
      const underlineMat = new MeshStandardNodeMaterial({
        color: '#ff2a38',
        emissive: '#ff2a38',
        emissiveIntensity: 1.3,
        side: DoubleSide,
        transparent: true,
        opacity: 1,
      });
      const underlineMesh = new Mesh(underlineGeom, underlineMat);
      underlineMesh.position.set(0, -0.54, 0.001);
      cardGroup.add(underlineMesh);
    }

    // ---- CAPTION TEXT ----
    const captionStr = captions[i];
    const captionObj = ctx.fontAtlas.createText(captionStr, {
      fontSize: 18,
      color: '#e8ecf2',
      align: 'center',
      letterSpacing: 0.08,
    });
    captionObj.position.set(0, -0.65, 0);
    cardGroup.add(captionObj);

    stripGroup.add(cardGroup);
  }

  // ---------- CINEMATIC PRIMITIVE ----------
  const parallaxPrim = ctx.primitives['parallax-scroll'](stripGroup, { intensity: 0.5 });

  // ---------- CLEANUP ----------
  root.userData.cleanup = () => {
    // Dispose materials & geometries
    cardMaterials.forEach((obj) => {
      obj.material.dispose();
      obj.geometry.dispose();
      obj.frameMat.dispose();
      obj.frameGeom.dispose();
    });
    backdropGeom.dispose();
    backdropMat.dispose();

    // Dispose texture if it was loaded
    texturePromise.then((tex) => {
      tex.dispose();
    });

    // Kill GSAP timelines (if any created later)
    gsap.globalTimeline.clear();

    // Primitive cleanup
    if (parallaxPrim && typeof parallaxPrim.cleanup === 'function') {
      parallaxPrim.cleanup();
    }

    // Remove lights and children
    root.traverse((child) => {
      if (child.isLight) {
        child.dispose?.();
      }
    });
  };

  // No direct handlers defined for this node
  root.userData.handlers = {};

  return root;
}
